contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 x) public {
        require(x == 0);

        uint256 beforeValue = c.value(); if (__ESBMC_reverted()) return;
        uint256 beforeRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterValue = c.value(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? afterValue == beforeValue
                : (beforeValue <= beforeRemaining
                    ? afterValue == beforeValue - (beforeValue / 100000)
                    : afterValue == 0)
        );
    }
}

