pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 x) internal {
        x = 0;
        uint256 beforeValue;
        try c.value() returns (uint256 __r) { beforeValue = __r; } catch { return; }
        uint256 beforeRemaining;
        try c.totalRemaining() returns (uint256 __r) { beforeRemaining = __r; } catch { return; }
        bool reverted;
        try c.getTokens() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterValue;
        try c.value() returns (uint256 __r) { afterValue = __r; } catch { return; }
        assertTrue(reverted
                ? afterValue == beforeValue
                : (beforeValue <= beforeRemaining
                    ? afterValue == beforeValue - (beforeValue / 100000)
                    : afterValue == 0));
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
